import{_ as e,o as t,c as r,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const k=JSON.parse('{"title":"2. Att förstå relationella data","description":"","frontmatter":{},"headers":[],"relativePath":"sv/chapters/02-att-forsta-relationella-data.md","filePath":"sv/chapters/02-att-forsta-relationella-data.md"}'),s={name:"sv/chapters/02-att-forsta-relationella-data.md"};function l(i,a,d,o,m,p){return t(),r("div",null,[...a[0]||(a[0]=[n(`<h1 id="_2-att-forsta-relationella-data" tabindex="-1">2. Att förstå relationella data <a class="header-anchor" href="#_2-att-forsta-relationella-data" aria-label="Permalink to &quot;2. Att förstå relationella data&quot;">​</a></h1><p>En bokhandel behöver veta vilka kunder den har, var de bor och vart deras beställningar ska levereras. Informationen beskriver olika saker, men sakerna hör ihop.</p><p>När vi organiserar data behöver vi därför bestämma vad som är en självständig företeelse, vad som är en egenskap och vad som är ett samband. Valen påverkar vilka frågor vi kan besvara och hur lätt informationen går att förändra.</p><h2 id="grund" tabindex="-1">Grund <a class="header-anchor" href="#grund" aria-label="Permalink to &quot;Grund&quot;">​</a></h2><h3 id="entiteter-och-attribut" tabindex="-1">Entiteter och attribut <a class="header-anchor" href="#entiteter-och-attribut" aria-label="Permalink to &quot;Entiteter och attribut&quot;">​</a></h3><p>En <strong>entitet</strong> är något vi vill hålla reda på, exempelvis en kund eller en adress. Ett <strong>attribut</strong> är en egenskap som vi vill registrera om entiteten.</p><p>För en kund kanske vi vill spara namn och e-postadress. För en adress behöver vi gata, postnummer och ort.</p><p><strong>customers</strong></p><table tabindex="0"><thead><tr><th>id</th><th>name</th><th>email</th></tr></thead><tbody><tr><td>1</td><td>Benjamin</td><td><a href="mailto:benjamin@example.com" target="_blank" rel="noreferrer">benjamin@example.com</a></td></tr><tr><td>2</td><td>Olof</td><td><a href="mailto:olof@example.com" target="_blank" rel="noreferrer">olof@example.com</a></td></tr><tr><td>3</td><td>Anaïs</td><td><a href="mailto:anais@example.com" target="_blank" rel="noreferrer">anais@example.com</a></td></tr></tbody></table><p>En <strong>entitet</strong> hör till modellen av verkligheten; en <strong>tabell</strong> är vårt sätt att representera den i databasen.</p><h3 id="identitet-–-vilken-kund-menar-vi" tabindex="-1">Identitet – vilken kund menar vi? <a class="header-anchor" href="#identitet-–-vilken-kund-menar-vi" aria-label="Permalink to &quot;Identitet – vilken kund menar vi?&quot;">​</a></h3><p>Det kan finnas två kunder med samma namn. Ett namn räcker alltså inte alltid för att identifiera en kund.</p><p>Vi kan därför tilldela varje kund ett eget id. Kolumnen <code>id</code> kan fungera som tabellens <strong>primärnyckel</strong> (<em>primary key</em>). Primärnyckelns värde måste vara unikt för varje rad och får inte vara <code>NULL</code>.</p><p>När vi vill hitta eller referera till en viss rad använder vi i första hand primärnyckeln. Skriver vi <code>WHERE id = 2</code> menar vi just Olofs rad, och därmed den information vi har lagrat om honom.</p><p>Primärnyckeln kan även bestå av flera kolumner, men här använder vi ett enda id.</p><h3 id="var-ska-adresserna-finnas" tabindex="-1">Var ska adresserna finnas? <a class="header-anchor" href="#var-ska-adresserna-finnas" aria-label="Permalink to &quot;Var ska adresserna finnas?&quot;">​</a></h3><p>Vi skulle kunna lägga adresserna direkt i kundtabellen.</p><table tabindex="0"><thead><tr><th>id</th><th>name</th><th>street</th><th>city</th></tr></thead><tbody><tr><td>1</td><td>Benjamin</td><td>Hemmagatan 1</td><td>Hemmavan</td></tr><tr><td>2</td><td>Olof</td><td>Parkvägen 2</td><td>Storfors</td></tr></tbody></table><p>Men om Benjamin vill registrera både en fakturaadress och en leveransadress? Vi skulle kunna lägga till fler kolumner, men vad händer när vi behöver en tredje adress?</p><p>Vi kan i stället dela upp informationen i två tabeller.</p><p><strong>customers</strong></p><table tabindex="0"><thead><tr><th>id</th><th>name</th></tr></thead><tbody><tr><td>1</td><td>Benjamin</td></tr><tr><td>2</td><td>Olof</td></tr><tr><td>3</td><td>Anaïs</td></tr></tbody></table><p><strong>addresses</strong></p><table tabindex="0"><thead><tr><th>id</th><th>customer_id</th><th>street</th><th>postal_code</th><th>city</th></tr></thead><tbody><tr><td>1</td><td>1</td><td>Hemmagatan 1</td><td>124 56</td><td>Hemmavan</td></tr><tr><td>2</td><td>1</td><td>Storgatan 4</td><td>154 32</td><td>Storfors</td></tr><tr><td>3</td><td>2</td><td>Parkvägen 2</td><td>154 32</td><td>Storfors</td></tr></tbody></table><p>Kolumnen <code>customer_id</code> innehåller värdet från <code>customers.id</code>. Den kan definieras som en <strong>främmande nyckel</strong> (<em>foreign key</em>).</p><p>En sådan begränsning hjälper databasen att kontrollera att en adress inte hänvisar till en kund som saknas. Att bara lagra samma id-värde räcker inte för att databasen ska kontrollera sambandet.</p><h3 id="en-till-manga-1-n" tabindex="-1">En-till-många (1:N) <a class="header-anchor" href="#en-till-manga-1-n" aria-label="Permalink to &quot;En-till-många (1:N)&quot;">​</a></h3><p>I vår modell kan en kund ha flera adresser, men varje adresspost hör till en kund.</p><p>Det är en <strong>en-till-många-relation</strong> (1:N).</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>customers                 addresses</span></span>
<span class="line"><span>┌────┬──────────┐         ┌────┬─────────────┐</span></span>
<span class="line"><span>│ id │ name     │         │ id │ customer_id │</span></span>
<span class="line"><span>├────┼──────────┤         ├────┼─────────────┤</span></span>
<span class="line"><span>│  1 │ Benjamin │◄────────│  1 │      1      │</span></span>
<span class="line"><span>│    │          │◄────────│  2 │      1      │</span></span>
<span class="line"><span>│  2 │ Olof     │◄────────│  3 │      2      │</span></span>
<span class="line"><span>└────┴──────────┘         └────┴─────────────┘</span></span></code></pre></div><p>Notera att två adressposter i vårt exempel kan ha samma <code>customer_id</code>. Det är just så en kund kan ha flera adresser.</p><h3 id="en-till-en-1-1" tabindex="-1">En-till-en (1:1) <a class="header-anchor" href="#en-till-en-1-1" aria-label="Permalink to &quot;En-till-en (1:1)&quot;">​</a></h3><p>I en <strong>en-till-en-relation</strong> hör varje post ihop med högst en post i den andra tabellen, och tvärtom.</p><p>Bokhandeln kanske lagrar särskilda kundinställningar separat, med högst en inställningspost per kund.</p><p>Ofta skulle informationen kunna ligga i samma tabell. Uppdelningen kan ändå vara lämplig om uppgifterna har andra åtkomstbehov eller bara finns för vissa kunder.</p><h3 id="manga-till-manga-m-n" tabindex="-1">Många-till-många (M:N) <a class="header-anchor" href="#manga-till-manga-m-n" aria-label="Permalink to &quot;Många-till-många (M:N)&quot;">​</a></h3><p>Anta att bokhandeln längre fram vill registrera produkter och deras författare.</p><p>En bok kan ha flera författare, och en författare kan ha skrivit flera böcker. Det är ett exempel på en <strong>många-till-många-relation</strong>.</p><p>Den kan representeras med en <strong>kopplingstabell</strong>, exempelvis <code>product_authors</code>, som innehåller <code>product_id</code> och <code>author_id</code>.</p><p>Vi behöver inte skapa dessa tabeller än. Vi återkommer till dem när bokhandelns sortiment växer.</p><h3 id="att-rita-en-datamodell" tabindex="-1">Att rita en datamodell <a class="header-anchor" href="#att-rita-en-datamodell" aria-label="Permalink to &quot;Att rita en datamodell&quot;">​</a></h3><p>Innan vi skapar tabeller kan vi rita upp vilka entiteter vi behöver och hur de hör ihop. Det kallas <strong>ER-modellering</strong> (<em>Entity–Relationship</em>).</p><p>Vår första modell kan beskrivas så här:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌───────────────┐    1       N    ┌────────────────┐</span></span>
<span class="line"><span>│ customers     │─────────────────│ addresses      │</span></span>
<span class="line"><span>├───────────────┤                 ├────────────────┤</span></span>
<span class="line"><span>│ id            │                 │ id             │</span></span>
<span class="line"><span>│ name          │                 │ customer_id    │</span></span>
<span class="line"><span>│ email         │                 │ street         │</span></span>
<span class="line"><span>└───────────────┘                 │ postal_code    │</span></span>
<span class="line"><span>                                  │ city           │</span></span>
<span class="line"><span>                                  └────────────────┘</span></span></code></pre></div><p>Papper och penna är ofta fullt tillräckligt. Det viktiga är att förstå modellen, inte att rita ett snyggt diagram.</p><h2 id="avancerat" tabindex="-1">Avancerat <a class="header-anchor" href="#avancerat" aria-label="Permalink to &quot;Avancerat&quot;">​</a></h2><h3 id="kardinalitet-och-valfrihet" tabindex="-1">Kardinalitet och valfrihet <a class="header-anchor" href="#kardinalitet-och-valfrihet" aria-label="Permalink to &quot;Kardinalitet och valfrihet&quot;">​</a></h3><p>När vi beskriver ett samband behöver vi ställa två frågor:</p><ul><li><strong>Hur många?</strong> Kan en kund ha en eller flera adresser?</li><li><strong>Är sambandet obligatoriskt?</strong> Måste varje kund ha en registrerad adress?</li></ul><p>En kund kan i vår modell ha noll, en eller flera adresser (0..N). Varje adresspost måste däremot höra till exakt en kund (1..1), om vi bestämmer att det är en regel i verksamheten.</p><p>Sådana regler är en del av datamodellen. De följer inte automatiskt av vad vi kallar tabellerna.</p><h3 id="nar-tva-kunder-delar-adress" tabindex="-1">När två kunder delar adress <a class="header-anchor" href="#nar-tva-kunder-delar-adress" aria-label="Permalink to &quot;När två kunder delar adress&quot;">​</a></h3><p>Två kunder kan bo på samma gata och samma nummer. Betyder det att de ska dela <em>samma adresspost</em>?</p><p>Inte nödvändigtvis.</p><p>I vår första modell har varje adresspost en ägare genom <code>customer_id</code>. Två kunder på samma fysiska adress kan därför ha varsin adresspost med samma gata och postnummer.</p><p>Om vi senare vill hantera en gemensam adresspost som flera kunder refererar till behöver vi förändra modellen. Vi skulle exempelvis kunna införa kopplingstabellen <code>customer_addresses</code>.</p><p>Det är en bra illustration av varför <strong>verksamhetens behov avgör hur informationen ska organiseras</strong>.</p><h3 id="nar-ett-samband-far-egna-attribut" tabindex="-1">När ett samband får egna attribut <a class="header-anchor" href="#nar-ett-samband-far-egna-attribut" aria-label="Permalink to &quot;När ett samband får egna attribut&quot;">​</a></h3><p>Anta att vi behöver markera vilken adress som används för leverans och vilken som används för fakturering.</p><p>Vi kan lägga till ett <code>address_type</code> i vår enkla adressmodell.</p><p>Men om flera kunder ska kunna dela samma adresspost blir adressens roll något som hör till <em>sambandet mellan kund och adress</em>, inte till själva gatan och postnumret. Då kan uppgiften ligga i kopplingstabellen.</p><p>Vi kommer tillbaka till detta när vi arbetar med datamodellering och normalisering.</p><h3 id="fran-adressregister-till-bokhandel" tabindex="-1">Från adressregister till bokhandel <a class="header-anchor" href="#fran-adressregister-till-bokhandel" aria-label="Permalink to &quot;Från adressregister till bokhandel&quot;">​</a></h3><p>Hittills har vi bara beskrivit kunder och adresser. Senare behöver vi även hålla reda på sortiment, produkter, författare, varukorgar och beställningar.</p><p>Det går att grovt skilja mellan:</p><ul><li><strong>Masterdata:</strong> relativt varaktiga uppgifter om exempelvis kunder och produkter.</li><li><strong>Referensdata:</strong> kontrollerade värden, exempelvis produkttyper.</li><li><strong>Transaktionsdata:</strong> uppgifter om verksamhetens händelser, exempelvis ordrar och orderrader.</li></ul><p>Det är användbara kategorier, men inte absoluta gränser. Författare är exempelvis oftast masterdata snarare än referensdata, eftersom de är självständiga företeelser med egna egenskaper.</p><p>Vi ska fortsätta bygga ut samma bokhandel allt eftersom vi behöver fler delar av SQL.</p><h3 id="relation-i-tva-betydelser" tabindex="-1">Relation i två betydelser <a class="header-anchor" href="#relation-i-tva-betydelser" aria-label="Permalink to &quot;Relation i två betydelser&quot;">​</a></h3><p>I ett ER-diagram beskriver en <em>relation</em> ett <strong>samband mellan entiteter</strong>.</p><p>I den matematiska relationsmodellen betyder ordet något annat: en relation är en mängd tupler över definierade attribut. Den kan förenklat liknas vid en tabell, men SQL-tabeller följer inte alltid alla den matematiska modellens egenskaper.</p><p>Orden är besläktade, men betydelserna är inte identiska.</p><h3 id="fran-modell-till-implementation" tabindex="-1">Från modell till implementation <a class="header-anchor" href="#fran-modell-till-implementation" aria-label="Permalink to &quot;Från modell till implementation&quot;">​</a></h3><p>ER-diagrammet hjälper oss att förstå vad vi vill beskriva innan vi börjar skriva SQL.</p><p>Så småningom kommer vi att skapa tabeller, ange primärnycklar och främmande nycklar och använda <code>JOIN</code> för att hämta information som finns i flera tabeller.</p><h2 id="reflektion" tabindex="-1">Reflektion <a class="header-anchor" href="#reflektion" aria-label="Permalink to &quot;Reflektion&quot;">​</a></h2><ol><li>Är en adress en självständig entitet eller en egenskap hos en kund? Vad avgör det?</li><li>Varför bör vi identifiera en kund med ett id snarare än ett namn?</li><li>Hur behöver modellen förändras om flera kunder ska kunna använda samma adresspost?</li></ol>`,77)])])}const v=e(s,[["render",l]]);export{k as __pageData,v as default};
